package verify

import (
	"fmt"
	"sort"
	"strings"
)

// DocPath of the verification map, relative to the module root.
const DocPath = "docs/verification.md"

// docIntro opens the verification map.
const docIntro = "# Verification map\n\n" +
	"<!-- Generated by `make verification` from the tests, /docs/requirements.md, /docs/deviations.md, and the simulator's kill matrix. Do not edit it by hand. -->\n\n" +
	"This document maps every requirement of maragudb to the tests that verify it. The IDs come from the documents that state the requirements: `AC-` marks an acceptance criterion and `INV-` a key invariant in [requirements.md](requirements.md), and `DEV-` a deviation from Postgres in [deviations.md](deviations.md). `MUT-` marks a mutant, a deliberate bug the checkers must catch, and `STATE-` an interesting state the simulator must reach.\n\n" +
	"The tests declare what they verify, and `make verification` generates this document from those declarations and the documents above. A test fails if the generated text differs from this file, if an ID has no test, or if a test names an ID that does not exist, so the map cannot go stale.\n\n" +
	"Each entry names the test's package, the test's name, and what the test asserts, in one line. The numbers behind each run, such as seeds, anomalies, and reached-state counts, are in the verification report on the summary page of every [CI run](https://github.com/maragudk/maragudb/actions/workflows/ci.yml).\n"

// GenerateDoc renders the verification map: for every ID, the tests that verify it, and the
// kill matrix of the mutants.
func GenerateDoc(c Catalog, covs []Coverage) string {
	byID := map[string][]Coverage{}
	for _, cov := range covs {
		for _, id := range cov.IDs {
			byID[id] = append(byID[id], cov)
		}
	}

	var b strings.Builder
	b.WriteString(docIntro)

	counts := map[string]int{}
	for _, r := range c.Requirements {
		counts[r.Kind()]++
	}
	detected := 0
	for _, m := range c.KillMatrix.Mutants {
		if m.Detected() {
			detected++
		}
	}
	b.WriteString("\n## At a glance\n\n")
	fmt.Fprintf(&b, "- %d acceptance criteria (`AC-`), %d key invariants (`INV-`), and %d deviations from Postgres (`DEV-`), each verified by at least one test.\n", counts["AC"], counts["INV"], counts["DEV"])
	fmt.Fprintf(&b, "- %d mutants (`MUT-`), deliberate bugs, of which %d are detected by the simulator's checkers within %d seeds.\n", len(c.KillMatrix.Mutants), detected, c.KillMatrix.Seeds)
	fmt.Fprintf(&b, "- %d interesting states (`STATE-`) that the simulator's fixed corpus must reach.\n", len(c.States))
	fmt.Fprintf(&b, "- %d declarations of coverage in the tests.\n", len(covs))

	sections := []struct{ kind, title string }{
		{"AC", "Acceptance criteria"},
		{"INV", "Key invariants"},
		{"DEV", "Deviations from Postgres"},
	}
	for _, sec := range sections {
		fmt.Fprintf(&b, "\n## %s\n", sec.title)
		for _, r := range c.Requirements {
			if r.Kind() != sec.kind {
				continue
			}
			fmt.Fprintf(&b, "\n### `%s`\n\n> %s\n\n", r.ID, r.Text)
			writeCoverage(&b, byID[r.ID])
		}
	}

	writeKillMatrix(&b, c.KillMatrix, byID)

	b.WriteString("\n## Reached states\n\n")
	b.WriteString("The fixed simulator corpus must reach every state at least once, or its test fails. The counts of each run are in the CI report.\n\n")
	b.WriteString("| ID | State | Antithesis assertion |\n|---|---|---|\n")
	for _, s := range c.States {
		fmt.Fprintf(&b, "| `%s` | %s | %q |\n", s.State, s.Description, s.Assertion)
	}
	var stateCovs []Coverage
	seen := map[string]bool{}
	for _, s := range c.States {
		for _, cov := range byID[string(s.State)] {
			if !seen[cov.Pos] {
				seen[cov.Pos] = true
				stateCovs = append(stateCovs, cov)
			}
		}
	}
	b.WriteString("\nVerified by:\n\n")
	writeCoverage(&b, stateCovs)
	return b.String()
}

func writeCoverage(b *strings.Builder, covs []Coverage) {
	if len(covs) == 0 {
		b.WriteString("- No test verifies this.\n")
		return
	}
	for _, cov := range covs {
		fmt.Fprintf(b, "- `%s` `%s`: %s\n", cov.Package, cov.Test, cov.What)
	}
}

func writeKillMatrix(b *strings.Builder, km KillMatrix, byID map[string][]Coverage) {
	b.WriteString("\n## Mutant kill matrix\n\n")
	fmt.Fprintf(b, "Every mutant runs in every simulator configuration below, with seeds 1 to %d, until a checker finds an anomaly. A configuration that never detects a mutant states why it cannot.\n\n", km.Seeds)
	b.WriteString("| Mutant | Detected in | First seed | Checkers |\n|---|---|---|---|\n")
	for _, m := range km.Mutants {
		n, applicable := 0, 0
		var first uint64
		checkers := map[string]bool{}
		for _, r := range m.Results {
			if r.Status != NotApplicable {
				applicable++
			}
			if r.Status != Detected {
				continue
			}
			n++
			if first == 0 || r.Seed < first {
				first = r.Seed
			}
			for _, c := range r.Checkers {
				checkers[c] = true
			}
		}
		seed := "none"
		if first > 0 {
			seed = fmt.Sprint(first)
		}
		var names []string
		for c := range checkers {
			names = append(names, c)
		}
		sort.Strings(names)
		fmt.Fprintf(b, "| `%s` %s | %d of %d configurations | %s | %s |\n", m.ID, m.Name, n, applicable, seed, strings.Join(names, ", "))
	}
	for _, m := range km.Mutants {
		fmt.Fprintf(b, "\n### `%s`\n\n%s\n\n", m.ID, m.Description)
		b.WriteString("| Configuration | Result |\n|---|---|\n")
		for _, r := range m.Results {
			var result string
			switch r.Status {
			case Detected:
				result = fmt.Sprintf("detected with seed %d by %s", r.Seed, strings.Join(r.Checkers, ", "))
			case Undetected:
				result = "cannot detect: " + r.Reason
			case NotApplicable:
				result = "not applicable: " + r.Reason
			}
			fmt.Fprintf(b, "| %s | %s |\n", r.Cell, result)
		}
		if covs := byID[m.ID]; len(covs) > 0 {
			b.WriteString("\nTargeted tests:\n\n")
			writeCoverage(b, covs)
		}
	}
}
